        dominated = np.all(objectives <= objectives[i], axis=1) & (objectives != objectives[i]).any(axis=1)
        if np.any(dominated):
            hypervolumes[i] = np.prod(ref_point - objectives[i]) - np.sum(np.prod(ref_point - objectives[dominated], axis=1))
        else:
            hypervolumes[i] = np.prod(ref_point - objectives[i])
    selected_idx = np.argmax(hypervolumes)
    base_solution = archive[selected_idx][0].copy()
    current_weight = np.sum(weight_lst * base_solution)

