        return np.zeros_like(weight_lst, dtype=int)

    # Select solution with highest hypervolume contribution (diversity)
    objectives = np.array([obj for _, obj in archive])
    ref_point = np.max(objectives, axis=0) + 1.0
    hypervolumes = np.zeros(len(archive))
    for i in range(len(archive)):
        dominated = np.all(objectives <= objectives[i], axis=1) & (objectives != objectives[i]).any(axis=1)
        if np.any(dominated):
