        else:
            hypervolumes[i] = np.prod(ref_point - objectives[i])
    selected_idx = np.argmax(hypervolumes)
    base_solution = archive[selected_idx][0].copy()
    current_weight = np.sum(weight_lst * base_solution)

    # Calculate adaptive marginal utilities with objective balancing
    obj1_mean = np.mean(objectives[:, 0])
    obj2_mean = np.mean(objectives[:, 1])
    obj1_std = np.std(objectives[:, 0])
    obj2_std = np.std(objectives[:, 1])

    alpha = obj1_std / (obj1_std + obj2_std + 1e-6)
    beta = obj2_std / (obj1_std + obj2_std + 1e-6)

