    objectives = np.array([obj for _, obj in archive])
    dominance_ranks = np.zeros(len(archive))
    for i in range(len(archive)):
        dominated_count = 0
        for j in range(len(archive)):
            if i != j and (objectives[j, 0] >= objectives[i, 0] and objectives[j, 1] >= objectives[i, 1]):
                dominated_count += 1
        dominance_ranks[i] = dominated_count

    crowding_distances = np.zeros(len(archive))
    for i in range(2):
        sorted_idx = np.argsort(objectives[:, i])
        crowding_distances[sorted_idx[0]] = crowding_distances[sorted_idx[-1]] = np.inf
        for j in range(1, len(archive)-1):
            crowding_distances[sorted_idx[j]] += (objectives[sorted_idx[j+1], i] - objectives[sorted_idx[j-1], i]) / (objectives[sorted_idx[-1], i] - objectives[sorted_idx[0], i] + 1e-6)

    combined_scores = dominance_ranks + crowding_distances
    selected_idx = np.argmax(combined_scores)
    base_solution = archive[selected_idx][0].copy()
    current_weight = np.sum(weight_lst * base_solution)

    # Calculate normalized marginal utilities and adaptive weights
    marginal_value1 = value1_lst / (weight_lst + 1e-6)
    marginal_value2 = value2_lst / (weight_lst + 1e-6)
    combined_utility = marginal_value1 + marginal_value2

    obj1_weight = np.mean(objectives[:, 0]) / (np.mean(objectives[:, 0]) + np.mean(objectives[:, 1]) + 1e-6)
    obj2_weight = 1.0 - obj1_weight

    # Cluster items
    high_threshold = np.quantile(combined_utility, 0.7)
    medium_threshold = np.quantile(combined_utility, 0.3)
    high_items = np.where(combined_utility >= high_threshold)[0]
    medium_items = np.where((combined_utility >= medium_threshold) & (combined_utility < high_threshold))[0]
    low_items = np.where(combined_utility < medium_threshold)[0]

    new_solution = base_solution.copy()

    # Phase 1: Flip high-utility items for under-represented objective
    if obj1_weight < obj2_weight:
        target_items = high_items[np.argsort(-marginal_value1[high_items])]
    else:
        target_items = high_items[np.argsort(-marginal_value2[high_items])]

    for item in target_items:
