                new_solution[item] = 1
                current_weight += weight_lst[item]

    # Phase 2: Probabilistic flips for medium-utility items
    if np.random.rand() < 0.3:
        if obj1_weight > obj2_weight:
            target_items = medium_items[np.argsort(-marginal_value1[medium_items])]
        else:
