                        if new_solution[item] == 0 and current_weight + weight_lst[item] <= capacity:
                            new_solution[item] = 1
                            current_weight += weight_lst[item]
                        elif new_solution[item] == 1 and np.random.random() < temp:
                            new_solution[item] = 0
                            current_weight -= weight_lst[item]

    # Two-phase feasibility restoration
    while current_weight > capacity:
