    if not archive:
        return np.zeros_like(weight_lst, dtype=int)

    # Adaptive selection: combine dominance and diversity
    objectives = np.array([obj for _, obj in archive])
    dominance_scores = np.zeros(len(archive))
    diversity_scores = np.zeros(len(archive))

    # Dominance score: count how many solutions are dominated by each solution
    for i in range(len(archive)):
        dominated_count = 0
        for j in range(len(archive)):
            if i != j and (objectives[i, 0] >= objectives[j, 0] and objectives[i, 1] >= objectives[j, 1]) and (objectives[i, 0] > objectives[j, 0] or objectives[i, 1] > objectives[j, 1]):
                dominated_count += 1
        dominance_scores[i] = dominated_count

    # Diversity score: average distance to neighbors in objective space
    for i in range(len(archive)):
        distances = []
        for j in range(len(archive)):
            if i != j:
                distances.append(np.linalg.norm(objectives[i] - objectives[j]))
        diversity_scores[i] = np.mean(distances) if distances else 0

    # Combined selection score (balance between dominance and diversity)
    selection_scores = 0.7 * dominance_scores + 0.3 * diversity_scores
    selected_idx = np.argmax(selection_scores)
    base_solution = archive[selected_idx][0].copy()
    current_weight = np.sum(weight_lst * base_solution)

    # Calculate normalized marginal utilities
    marginal_value1 = value1_lst / (weight_lst + 1e-6)
    marginal_value2 = value2_lst / (weight_lst + 1e-6)
    normalized_marginal = (marginal_value1 + marginal_value2) / (np.max(marginal_value1 + marginal_value2) + 1e-6)

    # Dynamic objective prioritization based on archive coverage
    obj1_coverage = np.std(objectives[:, 0])
    obj2_coverage = np.std(objectives[:, 1])
    obj1_priority = obj1_coverage / (obj1_coverage + obj2_coverage + 1e-6)
    obj2_priority = obj2_coverage / (obj1_coverage + obj2_coverage + 1e-6)

    new_solution = base_solution.copy()

    # Tiered local search with dynamic prioritization
    for item in np.argsort(-normalized_marginal):
        if np.random.rand() < obj1_priority:
            if marginal_value1[item] > marginal_value2[item]:
                if new_solution[item] == 1:
